package com.autoops.machine.controller;import com.autoops.machine.service.SshHostTrustService;import org.springframework.web.bind.annotation.*;import java.util.Map;@RestController @RequestMapping("/api/machines/{machineId}/ssh-trust")public class SshTrustController{private final SshHostTrustService service;public SshTrustController(SshHostTrustService s){service=s;}public record Trust(String hostKey,String fingerprint){}@PostMapping public void trust(@PathVariable Long machineId,@RequestBody Trust t){service.trust(machineId,t.hostKey(),t.fingerprint());}@PostMapping("/verify")public Map<String,Boolean> verify(@PathVariable Long machineId,@RequestBody Trust t){service.verify(machineId,t.hostKey());return Map.of("trusted",true);}}
